:root{--admin-navy:#08284d;--admin-navy2:#103b69;--admin-gold:#f5bd4d;--admin-ink:#172b45;--admin-muted:#73839a;--admin-line:#e0e8f2}
*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:var(--admin-ink);font:15px/1.5 Inter,system-ui,-apple-system,"Segoe UI",sans-serif}
.admin-layout{min-height:100vh}.side{position:fixed;inset:0 auto 0 0;width:254px;padding:24px 15px;background:linear-gradient(165deg,#0d315a,#061b34);color:#e7effa;display:flex;flex-direction:column;z-index:50;box-shadow:8px 0 28px #0b254512}
