/* Modern responsive settings UI */
.panel{padding:26px;margin:20px 0 23px;border-radius:19px;background:linear-gradient(145deg,#fff,#fcfdff);border:1px solid #e0e8f2;box-shadow:0 12px 32px #102f510a;position:relative;overflow:hidden}
