.btn,a.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:linear-gradient(135deg,#174b7f,#092b50);color:#fff;padding:11px 16px;border:0;border-radius:11px;text-decoration:none;font:inherit;font-weight:850;cursor:pointer;box-shadow:0 4px 0 #dce6f1;transition:transform .15s,box-shadow .15s}
