.notice{padding:14px 16px;border:1px solid #c9efdb;border-left:4px solid #38a875;border-radius:12px;background:#edfbf3;color:#176746;margin:12px 0}.error{border-color:#f3d1d1;border-left-color:#dc6c6c;background:#fff4f4;color:#982c2c}
